CREATE TABLE requirements (
  code  text PRIMARY KEY,
  title text NOT NULL
);
INSERT INTO requirements VALUES ('REQ-1', 'Giriş ekranı'), ('REQ-2', 'Rapor; PDF');

-- TO STDOUT: the rows go to the client as COPY data, not as a result set.
-- psql prints them; this runner reads results the way a plain query call
-- does, so all it shows is the command tag with the row count.
COPY requirements TO STDOUT WITH (FORMAT csv, HEADER);

-- Any query can be the source: that is how you export a join or a view.
COPY (SELECT code FROM requirements WHERE title LIKE 'Rapor%') TO STDOUT;

-- A file name instead of STDIN/STDOUT: the server process opens the file,
-- on the server's disk, as the server's OS account. That takes a role.
SELECT current_user,
       pg_has_role('pg_read_server_files', 'USAGE')      AS read_files,
       pg_has_role('pg_write_server_files', 'USAGE')     AS write_files,
       pg_has_role('pg_execute_server_program', 'USAGE') AS run_programs;

COPY requirements FROM 'C:/Users/ayse/Downloads/requirements.csv' WITH (FORMAT csv, HEADER);

files.examples/02_copy_in.go:
package main

import (
	"context"
	"fmt"
	"log"
	"os"
	"strings"

	"github.com/jackc/pgx/v5"
)

func main() {
	ctx := context.Background()
	conn, err := pgx.Connect(ctx, os.Getenv("DATABASE_URL"))
	if err != nil {
		log.Fatal(err)
	}
	defer conn.Close(ctx)
	_, err = conn.Exec(ctx, "CREATE TABLE requirements (code text PRIMARY KEY, title text, priority int)")
	if err != nil {
		log.Fatal(err)
	}

	// What psql's \copy does: send COPY ... FROM STDIN, then stream the bytes.
	load := func(label, data, extra string) {
		sql := "COPY requirements FROM STDIN WITH (FORMAT csv, HEADER MATCH, DELIMITER ';'" + extra + ")"
		tag, err := conn.PgConn().CopyFrom(ctx, strings.NewReader(data), sql)
		if err != nil {
			fmt.Println(label, err)
			return
		}
		fmt.Println(label, tag)
	}
	load("utf-8:  ", "code;title;priority\n"+
		"REQ-1;Giriş ekranı;1\n"+
		"REQ-2;\"Rapor; PDF\";\n"+
		"REQ-3;\"\";2\n", "")
	load("bom:    ", "\xEF\xBB\xBFcode;title;priority\r\nREQ-4;Arama;1\r\n", "")
	legacy := "code;title;priority\r\nREQ-5;\xddhracat \xfeablonu;3\r\n" // windows-1254
	load("1254:   ", legacy, "")
	load("1254+enc", legacy, ", ENCODING 'WIN1254'")

	rows, _ := conn.Query(ctx, `SELECT format('%s | %s | %s', code, quote_nullable(title),
		coalesce(priority::text, 'NULL')) FROM requirements ORDER BY code`)
	lines, err := pgx.CollectRows(rows, pgx.RowTo[string])
	if err != nil {
		log.Fatal(err)
	}
	fmt.Println(strings.Join(lines, "\n"))
}

files.examples/03_copy_out.go:
package main

import (
	"bytes"
	"context"
	"fmt"
	"log"
	"os"

	"github.com/jackc/pgx/v5"
)

func main() {
	ctx := context.Background()
	conn, err := pgx.Connect(ctx, os.Getenv("DATABASE_URL"))
	if err != nil {
		log.Fatal(err)
	}
	defer conn.Close(ctx)
	_, err = conn.Exec(ctx, `CREATE TABLE runs (case_code text, result text, note text, seconds numeric(6,2));
		INSERT INTO runs VALUES ('TC-1', 'geçti', NULL, 1.50),
		  ('TC-2', 'kaldı', E'tab\t"tırnak"', 12.25), ('TC-3', 'geçti', '', 0.75)`)
	if err != nil {
		log.Fatal(err)
	}

	// CopyTo streams the COPY data into any io.Writer: a file, an HTTP
	// response, a gzip.Writer. Here a buffer, printed with %q.
	export := func(label, prefix, sql string) {
		buf := bytes.NewBufferString(prefix)
		tag, err := conn.PgConn().CopyTo(ctx, buf, sql)
		fmt.Printf("%s: %v %v\n  %q\n", label, tag, err, buf.String())
	}
	export("text", "", "COPY (SELECT * FROM runs ORDER BY case_code) TO STDOUT")
	export("csv", "", "COPY (SELECT * FROM runs ORDER BY case_code) TO STDOUT WITH (FORMAT csv, HEADER)")
	export("excel", "\xEF\xBB\xBF", `COPY (SELECT case_code AS "Test", result AS "Sonuç",
		  replace(seconds::text, '.', ',') AS "Süre (sn)" FROM runs ORDER BY case_code)
		TO STDOUT WITH (FORMAT csv, HEADER, DELIMITER ';')`)
}
